}

/// Why a Private USD call failed. Copy follows the code, never the message.
enum ApiPrivateUsdErrorCode {
  relayerUnreachable,
  relayerRefused,
  relayerFee,
  ethereumUnreachable,
  railgunClosed,
  zcashWallet,
  depositUnpayable,
  zcashRejected,
  mismatch,
  tokensRefused,
  tokensNeeded,
  chainLagging,
  quoteExpired,
  makerUnavailable,
  makerBusy,
  amountRefused,
  fundingCostChanged,
  depositUnconfirmed,
  tooLate,
  busy,
  storeUnreadable,
  unavailable,
  routeBlocked,
  other,

  /// The call was cancelled (`private_usd_cancel`): never a failure.
  cancelled,

  /// A service or the node belongs to another deployment than this build
  /// pins: a contract that is not the pinned windows contract, or terms
  /// that are not the pin's. Never followed.
  wrongDeployment,
}

