/// Where a reverse conversion stands.
enum ApiReversePhase {
  /// A reviewed draft: nothing accepted or paid, not under way.
  quoted,
  accepting,

  /// The user's first approval: "Pay {debit}".
  awaitingFunding,
  sendingUsdc,
  confirmingEscrow,
  receivingZec,

  /// The user's second approval: "Authorize settlement".
  awaitingReady,
  settling,
  receiving,
  complete,
  refundWait,
  refunding,
  refundPayout,
  refunded,
  cancelled,
}

